def entry(t):
    slug, cover, cat, nar, nen, sar, sen, method, extra, kar, ken, types = t
    types = [x for x in types]
    if len(method) < 160:
        method += " State assumptions, write the deliverable in the user's language and report what was produced and where."
    kar = kar + EXTRA_AR.get(slug, [])
    ken = ken + EXTRA_EN.get(slug, [])
    return {"slug": slug, "name_ar": nar, "name_en": nen, "summary_ar": sar, "summary_en": sen,
            "expertise": method, "checks": extra + [CHK_SRC, CHK_OUT][: max(1, 4 - len(extra))],
            "keywords": kar + ken, "task_types": types, "category": cat, "cover": cover}

